<x-company.layout title="Activity log" description="Company actions and account changes">
    <form method="GET" class="grid items-end gap-3 rounded-sm border border-line bg-surface p-4 sm:grid-cols-2 xl:grid-cols-4"><label class="text-sm">Action<select name="action" class="mt-1 block w-full rounded-sm border border-line bg-surface p-3"><option value="">All actions</option>@foreach ($actions as $key => $label)<option value="{{ $key }}" @selected(request('action') === $key)>{{ $label }}</option>@endforeach</select></label><label class="text-sm">From<input type="date" name="from" value="{{ request('from') }}" class="mt-1 block w-full rounded-sm border border-line p-3"></label><label class="text-sm">Through<input type="date" name="to" value="{{ request('to') }}" class="mt-1 block w-full rounded-sm border border-line p-3"></label><button class="btn btn-primary">Filter</button></form>
    <x-seller.data-table label="Company activity" responsive="scroll" class="rounded-sm! bg-surface! shadow-none!">
        <x-slot:head><tr>@foreach (['Date (Philippine time)', 'Account', 'Action', 'Subject', 'Details', 'IP address'] as $label)<th class="p-3">{{ $label }}</th>@endforeach</tr></x-slot:head>
        @forelse ($logs as $log)<tr><td class="p-3">{{ $log->created_at->timezone('Asia/Manila')->format('M d, Y g:i A') }}</td><td class="p-3">{{ $log->user?->name ?? 'Deleted account' }}</td><td class="p-3">{{ $actions[$log->action] ?? $log->action }}</td><td class="p-3">{{ str(class_basename($log->subject_type))->headline() }}</td><td class="p-3 text-xs">@if (!empty($log->meta['fields']))Changed fields: {{ implode(', ', $log->meta['fields']) }}@endif @if (isset($log->meta['recipients']))Recipients: {{ $log->meta['recipients'] }}@endif</td><td class="p-3">{{ $log->ip_address ?? '-' }}</td></tr>@empty<tr><td colspan="6" class="p-6 text-center">No activity matches these filters.</td></tr>@endforelse
    </x-seller.data-table>{{ $logs->links() }}
